 flows={};now=None
 def fb(f):
  node=cfg['fallback']; vals=(f.hist[:cfg['prefix_width']]+[0]*cfg['prefix_width'])[:cfg['prefix_width']]
  while 'class' not in node: node=node['le'] if vals[node['feature']]<=node['threshold'] else node['gt']
  return node['class']
 def decision(f,reason,time,rule=None,cls=None):
  if cls is None: cls=fb(f)
