  elif op=='tick':ev+=advance(req['time'])
  elif op=='close':
   f=flows[req['flow']];ev+=advance(req['time'])
   if f.dec is None:ev.append(decision(f,'end',req['time']))
   cls,reason,rule=f.dec
   ev.append({'type':'closed','flow':f.id,'packets':f.n,'matches':f.matches,'class':cls,'reason':reason,'rule':rule})
   del flows[f.id]
